import React from 'react';
import logo from '../logo.svg';

const Home = () => {
  return (
    <div className="min-h-[calc(100vh-4rem)] bg-gradient-to-r from-blue-500 to-purple-600 flex items-center justify-center">
      <div className="bg-white p-10 rounded-2xl shadow-2xl text-center max-w-md">
        <img src={logo} className="h-24 w-24 mx-auto animate-spin" alt="logo" />
        <h1 className="text-4xl font-bold text-gray-800 mt-4">
          Welcome to MyApp
        </h1>
        <p className="text-gray-600 mt-2 text-lg">
          Built with React + Tailwind CSS
        </p>
        <div className="mt-6 space-x-4">
          <button className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-6 rounded-full transition duration-300 transform hover:scale-105">
            Get Started
          </button>
          <button className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-6 rounded-full transition duration-300 transform hover:scale-105">
            Learn More
          </button>
        </div>
      </div>
    </div>
  );
};

export default Home;
